3	import { useOptimistic, useTransition } from 'react'
4	import { toast } from 'sonner'
5	
6	export function useOptimisticReorder<T extends { id: string }>(
7	  items: T[],
8	  reorderAction: (orderedIds: string[]) => Promise<void>,
9	) {
10	  const [optimisticItems, reorderOptimistically] = useOptimistic(
11	    items,
12	    (_current: T[], reordered: T[]) => reordered,
13	  )
14	  const [, startTransition] = useTransition()
15	
16	  function handleReorder(reordered: T[], containerRef?: React.RefObject<HTMLElement | null>) {
17	    startTransition(async () => {
18	      reorderOptimistically(reordered)
19	      try {
20	        await reorderAction(reordered.map(i => i.id))
21	      } catch {
22	        // useOptimistic auto-restores original order
23	        // Add red-pulse on container element if ref provided
24	        if (containerRef?.current) {
25	          containerRef.current.setAttribute('data-reorder-error', 'true')
26	          setTimeout(() => {
27	            containerRef.current?.removeAttribute('data-reorder-error')
28	          }, 600)
29	        }
30	        toast.error("Couldn't reorder · Retry")
31	      }
32	    })
33	  }
34	
35	  return { optimisticItems, handleReorder }
36	}
